select:
SELECT b.name, b.avatar, a.content, date_format(a.created_time,'%Y-%m-%d %H:%i:%s') as created_time, a.id, a.parent_comment_id, b.userid FROM jml_comments a LEFT JOIN jml_staff b ON a.created_staff_id = b.id
a.sales_report_id = #{salesReportId}
order by a.created_time desc

SELECT b.name, b.avatar, a.content, date_format(a.created_time,'%Y-%m-%d %H:%i:%s') as created_time, a.id, b.userid FROM jml_comments a LEFT JOIN jml_staff b ON a.created_staff_id = b.id
a.top_comment_id = #{topCommentId}
order by a.parent_comment_id,a.id desc
